// ── parametric_spline_surface_entity.hpp ──
inline void to_json(nlohmann::json& j, SplineSurfacePatch const& o) {
    j = nlohmann::json::object();
    { auto a = nlohmann::json::array();
      for (int i = 0; i < 16; ++i) a.push_back(o.coeff_x[i]);
      j["coeff_x"] = std::move(a); }
    { auto a = nlohmann::json::array();
      for (int i = 0; i < 16; ++i) a.push_back(o.coeff_y[i]);
      j["coeff_y"] = std::move(a); }
    { auto a = nlohmann::json::array();
      for (int i = 0; i < 16; ++i) a.push_back(o.coeff_z[i]);
      j["coeff_z"] = std::move(a); }
}
inline void from_json(nlohmann::json const& j, SplineSurfacePatch& o) {
    { auto const& a = j.at("coeff_x");
      if (!a.is_array() || a.size() != 16)
          throw nlohmann::json::type_error::create(302, "SplineSurfacePatch.coeff_x expects 16-element array", &a);
      for (int i = 0; i < 16; ++i) a.at(i).get_to(o.coeff_x[i]); }
    { auto const& a = j.at("coeff_y");
      if (!a.is_array() || a.size() != 16)
          throw nlohmann::json::type_error::create(302, "SplineSurfacePatch.coeff_y expects 16-element array", &a);
      for (int i = 0; i < 16; ++i) a.at(i).get_to(o.coeff_y[i]); }
    { auto const& a = j.at("coeff_z");
      if (!a.is_array() || a.size() != 16)
          throw nlohmann::json::type_error::create(302, "SplineSurfacePatch.coeff_z expects 16-element array", &a);
      for (int i = 0; i < 16; ++i) a.at(i).get_to(o.coeff_z[i]); }
}

